function clamp(v,min,max){return Math.max(min,Math.min(max,v))}export function extractBorderStats(data,w,h){const borderThickness=Math.max(2,Math.floor(Math.min(w,h)*.04));let r=0,g=0,b=0,n=0;for(let y=0;y<h;y++){for(let x=0;x<w;x++){if(y<borderThickness||y>=h-borderThickness||x<borderThickness||x>=w-borderThickness){const idx=(y*w+x)*4;if(data[idx+3]<20)continue;r+=data[idx];g+=data[idx+1];b+=data[idx+2];n++}}}if(!n){return{r:240,g:240,b:240,luma:240,spread:0}}r/=n;g/=n;b/=n;const luma=.299*r+.587*g+.114*b;let spread=0;for(let y=0;y<h;y+=2){for(let x=0;x<w;x+=2){if(y<borderThickness||y>=h-borderThickness||x<borderThickness||x>=w-borderThickness){const idx=(y*w+x)*4;if(data[idx+3]<20)continue;spread+=Math.hypot(data[idx]-r,data[idx+1]-g,data[idx+2]-b)}}}spread/=Math.max(1,n/4);return{r:r,g:g,b:b,luma:luma,spread:spread}}export function extractPartMask(data,w,h){const bg=extractBorderStats(data,w,h);const mask=new Uint8Array(w*h);const threshold=clamp(24+bg.spread*1.35,26,78);let partPixels=0;for(let i=0;i<w*h;i++){const idx=i*4;const a=data[idx+3];if(a<36){mask[i]=0;continue}const pr=data[idx];const pg=data[idx+1];const pb=data[idx+2];const dist=Math.hypot(pr-bg.r,pg-bg.g,pb-bg.b);const luma=.299*pr+.587*pg+.114*pb;const isDarkPart=dist>threshold&&luma<Math.max(160,bg.luma-15);if(isDarkPart){mask[i]=255;partPixels++}else{mask[i]=0}}if(partPixels<w*h*.02){mask.fill(255);partPixels=w*h}return{mask:mask,partPixels:partPixels,bg:bg,threshold:threshold}}